public void notifyUser(String text, int duration, String id){
        if(duration == Snackbar.LENGTH_SHORT)
            duration = 2000;
        else if (duration == Snackbar.LENGTH_LONG)
            duration = 3500;

        displayMessage(text, duration, id);
    }
